-- ════════════════════════════════════════════════════════════════
-- القياس v5.1: إصلاحات ما قبل التفعيل (المرحلة ز) على baseline-v5 وpost-v3 غير المفعّلتين
-- ════════════════════════════════════════════════════════════════
-- مولَّد بـ scripts/questions/build-v5_1.mjs من supabase/content/questions/v5 وscripts/questions/edits-v5_1.mjs
-- 1) أطوال الخيارات في 48 فقرة: المفتاح لا يكون الأطول ولا يتجاوز وسيط الخيارات بأكثر من 10% (الدرجات والمواضع ثابتة)
-- 2) استبدال 12 فقرة معرفية كانت استدعاءً لمسميات أُطر الكتيب بفقرات مفاهيم عامة، بالرمز والمعرّف نفسيهما
-- 3) الزمن التقديري الواقعي: baseline-v5 = 50، post-v3 = 55 دقيقة
-- 97 صفًا يتغير. يتطلب 20261102100000_leaders_instruments_v5.sql، ويسبق 20261102100100_leaders_activate_v5.sql.
-- يرفض التطبيق إن كان لأي من الأداتين قياس مبدوء، لأن الاستبدال يغيّر معنى الفقرة. آمن لإعادة التشغيل.
do $$ begin
  if exists (select 1 from leaders.assessments a join leaders.instruments i on i.id = a.instrument_id where i.key in ('baseline-v5', 'post-v3')) then
    raise exception 'v5.1: لأداتي v5 قياسات مبدوءة؛ لا تُعدَّل فقراتهما بعد ذلك';
  end if;
end $$;

-- baseline-v5: 37 فقرة
update leaders.questions q set text_ar = 'في مراجعة مرحلية: المشروع ضمن الموعد، لكن دراسة حديثة تظهر أن الطلب على الخدمة أقل بكثير مما بُني عليه المبرر. ما القرار الأنسب؟', options = '[{"label":"الاستمرار كما هو مع تحديث دراسة الطلب في المرحلة القادمة","score":2},{"label":"الاستمرار لأن الأداء ضمن الخطة والميزانية المعتمدتين","score":1},{"label":"عرض المبرر المحدث على اللجنة لتقرر الاستمرار أو التعديل","score":4},{"label":"تسريع التنفيذ لإطلاق الخدمة قبل أن يتراجع الطلب أكثر","score":0}]'::jsonb, competency_ar = 'قرار البوابة', chapter_key = 'ch3'
  from leaders.instruments i where i.id = q.instrument_id and i.key = 'baseline-v5' and q.code = 'M-S2B';
